import sys
from fractions import Fraction

data = sys.stdin.read().split()
m, q = int(data[0]), int(data[1])
p = 2
edges = []
for _ in range(m):
    edges.append((data[p], data[p + 1], int(data[p + 2])))
    p += 3
out = []
for _ in range(q):
    f, t = data[p], data[p + 1]
    p += 2
    if f == t:
        out.append('1/1')
        continue
    best = {f: Fraction(1)}
    changed = True
    while changed:
        changed = False
        for a, b, r in edges:
            if a in best and b not in best:
                best[b] = best[a] * r
                changed = True
            if b in best and a not in best:
                best[a] = best[b] / r
                changed = True
    if t in best:
        out.append(f'{best[t].numerator}/{best[t].denominator}')
    else:
        out.append('-1')
print('\n'.join(out))

