import java.util.*;
import java.io.*;

public class Main {
    static String[] convert(String[][] facts, long[] rates, String[][] queries) {
        // Write your solution here
        String[] res = new String[queries.length];
        Arrays.fill(res, "-1");
        return res;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int m = Integer.parseInt(st.nextToken());
        int q = Integer.parseInt(st.nextToken());
        String[][] facts = new String[m][2];
        long[] rates = new long[m];
        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            facts[i][0] = st.nextToken();
            facts[i][1] = st.nextToken();
            rates[i] = Long.parseLong(st.nextToken());
        }
        String[][] queries = new String[q][2];
        for (int i = 0; i < q; i++) {
            st = new StringTokenizer(br.readLine());
            queries[i][0] = st.nextToken();
            queries[i][1] = st.nextToken();
        }
        String[] res = convert(facts, rates, queries);
        StringBuilder sb = new StringBuilder();
        for (String s : res) sb.append(s).append('\n');
        System.out.print(sb);
    }
}
